import React, { useState, useEffect } from "react";
import axios from "axios";

const SafetyCheck = () => {
  const [location, setLocation] = useState({ latitude: null, longitude: null });
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  // Step 1: Get user's live location
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setLocation({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          });
        },
        (error) => {
          console.error("Error getting location:", error);
          setMessage("❌ Unable to access location.");
        }
      );
    } else {
      setMessage("⚠️ Geolocation not supported by your browser.");
    }
  }, []);

  // Step 2: Send location to backend
  const checkSafety = async () => {
    if (!location.latitude || !location.longitude) {
      setMessage("📍 Waiting for location...");
      return;
    }

    setLoading(true);
    try {
      const response = await axios.post("http://localhost:5000/api/safety/check", {
        latitude: location.latitude,
        longitude: location.longitude,
      });

      setMessage(response.data.message);
    } catch (error) {
      console.error(error);
      setMessage("⚠️ Error checking safety.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ textAlign: "center", marginTop: "50px", fontFamily: "Poppins, sans-serif" }}>
      <h1>🧭 Smart Tourist Safety Check</h1>
      <p>
        <strong>Latitude:</strong> {location.latitude?.toFixed(4)} |{" "}
        <strong>Longitude:</strong> {location.longitude?.toFixed(4)}
      </p>
      <button
        onClick={checkSafety}
        disabled={loading}
        style={{
          padding: "10px 20px",
          backgroundColor: "#007bff",
          color: "white",
          border: "none",
          borderRadius: "8px",
          cursor: "pointer",
        }}
      >
        {loading ? "Checking..." : "Check Safety"}
      </button>
      <p style={{ marginTop: "20px", fontSize: "18px" }}>{message}</p>
    </div>
  );
};

export default SafetyCheck;
